SELECT COUNT(*)
FROM MEMBER
WHERE MEMBER_ID = #{memberId}

SELECT COUNT(*)
FROM MEMBER
WHERE NICKNAME = #{nickname}

SELECT COUNT(*)
FROM MEMBER
WHERE EMAIL = #{email}

mapper.update:
UPDATE MEMBER
SET NICKNAME = #{nickname},
    NICKNAME_CHANGED_AT = SYSDATE
WHERE MEMBER_NO = #{memberNo}
  AND STATUS = 'ACTIVE'
  AND (
      NICKNAME_CHANGED_AT IS NULL
      OR NICKNAME_CHANGED_AT <= SYSDATE - 30
  )
  AND NICKNAME != #{nickname}

UPDATE MEMBER
SET PROFILE_IMAGE = #{profileImage}
WHERE MEMBER_NO = #{memberNo}
  AND STATUS = 'ACTIVE'
